import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import { certificate, courseUrl } from '../../common/api';
import CertificateSvg, { downloadSvg, loadSvg } from '../../common/components/CertificateSvg';
import { t } from '../components/util';

/**
 * /certificates/:code — for the member who earned it, the certificate itself,
 * ready to print (or save as PDF from the print dialog) or download; for
 * anyone else with the link, a short verification that it is genuine, with
 * the certificate under it. The certificate is SVG laid out by the server
 * (Certificates\Layout) and shaped by the browser, so every script reads
 * right; the printout and the download are that same SVG, and the share image
 * is the same layout drawn as a JPEG.
 */
export default class CertificatePage extends Page {
  cert = null;
  svg = '';
  missing = false;
  downloading = false;
  oninit(vnode) {
    super.oninit(vnode);
    app.setTitle(extractText(t('certificate.title')));
    certificate(String(m.route.param('code') || '').toLowerCase()).then(({
      data
    }) => {
      this.cert = data;
      m.redraw();
      loadSvg(data.svgUrl).then(svg => {
        this.svg = svg;
        m.redraw();
      }, () => {
        // Without the SVG, the share image stands in.
        this.svg = 'failed';
        m.redraw();
      });
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  view() {
    const cert = this.cert;
    return m(PageStructure, {
      className: "SyllabusCertificatePage",
      loading: !cert && !this.missing
    }, this.missing ? m("div", {
      className: "SyllabusVerify SyllabusVerify--invalid"
    }, m(Icon, {
      name: "fas fa-circle-xmark"
    }), m("h2", null, t('certificate.invalid'))) : cert ? cert.isOwner ? this.certificate(cert) : this.verify(cert) : null);
  }
  date(cert) {
    return dayjs(cert.issuedAt).format('LL');
  }

  /** The certificate: the SVG once it's here, the share image if it can't load. */
  image(cert) {
    const label = extractText(t('certificate.share_title', {
      name: cert.userName,
      course: cert.courseTitle
    }));
    if (this.svg === 'failed') return m("img", {
      className: "SyllabusCertificate-image",
      src: cert.imageUrl,
      width: "2400",
      height: "1697",
      alt: label
    });
    if (!this.svg) return m("div", {
      className: "SyllabusCertificate-image",
      "aria-busy": "true"
    });
    return m(CertificateSvg, {
      svg: this.svg
    });
  }
  download(cert) {
    if (!this.svg || this.svg === 'failed') {
      window.location.href = cert.imageUrl + '&download=1';
      return;
    }
    this.downloading = true;
    downloadSvg(this.svg, 'certificate-' + cert.code + '.jpg').then(() => this.downloading = false, () => {
      // The browser couldn't draw it: the server's image instead.
      this.downloading = false;
      window.location.href = cert.imageUrl + '&download=1';
    }).finally(() => m.redraw());
  }
  certificate(cert) {
    return m("div", {
      className: "SyllabusCertificateWrap"
    }, m("div", {
      className: "SyllabusCertificate-actions"
    }, m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-print",
      onclick: () => window.print()
    }, t('certificate.print')), m(Button, {
      className: "Button",
      icon: "fas fa-download",
      loading: this.downloading,
      disabled: !this.svg,
      onclick: () => this.download(cert)
    }, t('certificate.download')), m(Button, {
      className: "Button",
      icon: "fas fa-link",
      onclick: () => navigator.clipboard?.writeText(cert.verifyUrl).then(() => app.alerts.show({
        type: 'success'
      }, t('certificate.copied')))
    }, t('certificate.copy_link')), cert.course ? m(Link, {
      className: "Button Button--link",
      href: courseUrl(cert.course)
    }, t('certificate.back')) : null), m("article", {
      className: "SyllabusCertificate"
    }, this.image(cert)));
  }
  verify(cert) {
    return m("div", {
      className: "SyllabusVerify"
    }, m(Icon, {
      name: "fas fa-circle-check"
    }), m("h2", null, t('certificate.verified')), m("p", null, t('certificate.verified_text', {
      name: cert.userName,
      course: cert.courseTitle,
      date: this.date(cert)
    })), m("p", {
      className: "helpText"
    }, t('certificate.issued_by_forum', {
      forum: app.forum.attribute('title')
    })), cert.course ? m(Link, {
      className: "Button",
      href: courseUrl(cert.course)
    }, t('certificate.see_course')) : null, m("article", {
      className: "SyllabusCertificate SyllabusCertificate--shared"
    }, this.image(cert)));
  }
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/pages/CertificatePage', CertificatePage);